<style>
	.profile-container {
		width: 100%;
		height: 100%;
		max-width: 35vw;
		display: flex;
		flex-direction: column;
		overflow: hidden;
	}

	.profile-svg {
		width: 100%;
		height: auto;
		flex-shrink: 0;
	}

	/* Natural blink cadence with a brief closed pause */
	:global(#eyes) {
		transform-box: fill-box; /* make transform-origin use the group's bounds */
		transform-origin: 50% 50%; /* center of the eyes group */
		animation: blink 6s infinite;
	}

	/* Keep strokes from getting fat/skinny during the blink (optional) */
	:global(#eyes),
	:global(#eyes *) {
		vector-effect: non-scaling-stroke;
	}

	@keyframes blink {
		0% {
			transform: scaleY(1);
		}
		2% {
			transform: scaleY(0.1);
		} /* close quickly */
		4% {
			transform: scaleY(1);
		} /* open */
		48% {
			transform: scaleY(1);
		} /* idle */
		50% {
			transform: scaleY(0.1);
		} /* a second blink in the cycle */
		52% {
			transform: scaleY(1);
		}
		100% {
			transform: scaleY(1);
		}
	}

	/* Respect reduced motion preferences */
	@media (prefers-reduced-motion: reduce) {
		:global(#eyes) {
			animation: none;
		}
	}
</style>
